#!/usr/bin/env bash
# chromium-keyring — SUPERSEDED by secretsmith (mesh project).
# Thin shim for muscle memory; one truth lives in secretsmith.
# NOTE: the old `key` subcommand was removed — the raw os_crypt secret is never printed.
case "${1:-check}" in
  check) exec secretsmith check ;;
  attrs) exec secretsmith search --schema chromium ;;
  *) echo "chromium-keyring: superseded by secretsmith; usage: chromium-keyring {check|attrs}" >&2; exit 2 ;;
esac

// @estate/keypool — config: minimal YAML parser, secrets file.
// Port of herd-keypool.py's custom simple YAML parser (strict subset).

import type { PoolConfig } from "./types.js";
import { readFileSync, existsSync } from "node:fs";

function parseScalar(s: string): unknown {
  s = s.trim();
  if (s === "" || s === "~" || s === "null") return null;
  if (s === "true") return true;
  if (s === "false") return false;
  if (/^-?\d+$/.test(s)) return parseInt(s, 10);
  if (/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
  if (
    (s.startsWith('"') && s.endsWith('"')) ||
    (s.startsWith("'") && s.endsWith("'"))
  ) {
    return s.slice(1, -1);
  }
  if (s.startsWith("[") && s.endsWith("]")) {
    const inner = s.slice(1, -1).trim();
    if (!inner) return [];
    return inner.split(",").map((x) => parseScalar(x.trim()));
  }
  if (s.startsWith("{") && s.endsWith("}")) {
    const inner = s.slice(1, -1).trim();
    const obj: Record<string, unknown> = {};
    if (inner) {
      for (const part of splitTop(inner, ",")) {
        const ci = part.indexOf(":");
        if (ci > 0)
          obj[part.slice(0, ci).trim()] = parseScalar(part.slice(ci + 1));
      }
    }
    return obj;
  }
  return s;
}

/** Split on sep, ignoring sep inside {} or []. */
function splitTop(s: string, sep: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let cur = "";
  for (const ch of s) {
    if (ch === "{" || ch === "[") depth++;
    else if (ch === "}" || ch === "]") depth--;
    if (ch === sep && depth === 0) {
      out.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  out.push(cur);
  return out;
}

interface Frame {
  indent: number;
  container: Record<string, unknown> | unknown[];
  /** key in parent that holds this container (for list conversion) */
  key?: string;
  parent?: Record<string, unknown> | unknown[];
}

/**
 * Parse the strict YAML subset used by keypools.yaml:
 * maps, nested maps, lists of scalars, lists of inline maps.
 */
export function parseSimpleYaml(text: string): Record<string, unknown> {
  const root: Record<string, unknown> = {};
  const stack: Frame[] = [{ indent: -1, container: root }];

  const lines = text.split("\n");
  for (let li = 0; li < lines.length; li++) {
    const raw = lines[li];
    // strip comments (naive: # not inside quotes — good enough for our files)
    const hashIdx = raw.indexOf("#");
    const line = (hashIdx >= 0 ? raw.slice(0, hashIdx) : raw).replace(
      /\s+$/,
      "",
    );
    if (!line.trim()) continue;

    const indent = line.length - line.trimStart().length;
    const content = line.trim();

    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) {
      stack.pop();
    }
    const frame = stack[stack.length - 1];
    let container = frame.container;

    // List item?
    if (content.startsWith("- ") || content === "-") {
      // Ensure container is an array (convert placeholder map if needed)
      if (!Array.isArray(container)) {
        if (
          frame.key !== undefined &&
          frame.parent &&
          !Array.isArray(frame.parent)
        ) {
          const arr: unknown[] = [];
          (frame.parent as Record<string, unknown>)[frame.key] = arr;
          frame.container = arr;
          container = arr;
        } else {
          throw new Error(
            `YAML: list item under non-list at line ${li + 1}: ${raw}`,
          );
        }
      }
      const valStr = content.startsWith("- ") ? content.slice(2).trim() : "";
      if (!valStr) {
        const item: Record<string, unknown> = {};
        (container as unknown[]).push(item);
        stack.push({ indent, container: item });
      } else if (valStr.includes(":") && !valStr.startsWith("{")) {
        // "- key: value" map item
        const ci = valStr.indexOf(":");
        const k = valStr.slice(0, ci).trim();
        const v = valStr.slice(ci + 1).trim();
        const item: Record<string, unknown> = {};
        item[k] = v ? parseScalar(v) : {};
        (container as unknown[]).push(item);
        if (!v) stack.push({ indent, container: item });
      } else {
        (container as unknown[]).push(parseScalar(valStr));
      }
      continue;
    }

    // Map entry "key: value"
    const ci = content.indexOf(":");
    if (ci < 0) throw new Error(`YAML: no colon at line ${li + 1}: ${raw}`);
    const key = content.slice(0, ci).trim();
    const valStr = content.slice(ci + 1).trim();

    if (Array.isArray(container)) {
      throw new Error(`YAML: map key under list at line ${li + 1}: ${raw}`);
    }
    const map = container as Record<string, unknown>;
    if (!valStr) {
      // nested block — placeholder, may become list on "- " children
      const placeholder: Record<string, unknown> = {};
      map[key] = placeholder;
      stack.push({ indent, container: placeholder, key, parent: map });
    } else {
      map[key] = parseScalar(valStr);
    }
  }

  return root;
}

/** Parse one `KEY=VALUE` line (optionally `export KEY='VALUE'`). Strips ONE
 * matching pair of surrounding quotes from the value — secretsmith env emits
 * shell-quoted exports, and storing the literal quotes corrupts every Bearer
 * header downstream (the 2026-10-26 mass-down: valid keys 401'd as
 * "Missing Authentication header" because the stored value was `sk-...'`). */
export function parseEnvLine(line: string): [string, string] | undefined {
  let t = line.trim();
  if (!t || t.startsWith("#")) return undefined;
  if (t.startsWith("export ")) t = t.slice(7).trim();
  const eq = t.indexOf("=");
  if (eq <= 0) return undefined;
  const k = t.slice(0, eq).trim();
  let v = t.slice(eq + 1).trim();
  if (
    v.length >= 2 &&
    ((v.startsWith("'") && v.endsWith("'")) ||
      (v.startsWith('"') && v.endsWith('"')))
  ) {
    v = v.slice(1, -1);
  }
  return [k, v];
}

/** Load secrets from KEY=VALUE file, merged with the process environment.
 *
 * Merge order: ambient process.env first, then an explicit secrets file record
 * (the local override — its quote-stripping must be observable, see
 * test/quotes.test.ts), then a keyring gap-fill via `secretsmith env` for
 * key-shaped names the file+env don't already define. Production post-cutover
 * has no secrets file (warn path), so this ordering is prod-neutral.
 */
export function loadSecrets(path: string): Map<string, string> {
  const out = new Map<string, string>();
  for (const [k, v] of Object.entries(process.env)) {
    if (typeof v === "string" && v.length > 0) out.set(k, v);
  }
  if (!existsSync(path)) {
    // ~/.secrets was the pre-keyring fallback record (AGENTS rule 3) and is
    // gone after the keyring cutover; the secretsmith-injected process env is
    // the SSOT now, so a missing file is a warn, not a fatal boot failure.
    console.warn(
      `[keypool] secrets file not found: ${path}; falling back to process env (keyring SSOT)`,
    );
  } else {
    for (const line of readFileSync(path, "utf8").split("\n")) {
      const parsed = parseEnvLine(line);
      if (parsed) out.set(parsed[0], parsed[1]);
    }
  }
  // The pitchfork-managed daemon has NO keyring env in its [env] block
  // (secrets are in the keyring SSOT). Make the daemon self-sufficient:
  // shell out to `secretsmith env` once and import its exports, so every
  // pool (GEMINI_EAP_KEY_*, NIM_*, ...) resolves without a wrapper in the
  // supervisor. Gap-fill only — never overrides file/env values.
  // Never logs the values.
  try {
    const proc = Bun.spawnSync(["secretsmith", "env"], {
      stdout: "pipe",
      stderr: "ignore",
    });
    if (proc.exitCode === 0) {
      const text = new TextDecoder().decode(proc.stdout);
      for (const line of text.split("\n")) {
        const parsed = parseEnvLine(line);
        if (!parsed) continue;
        const [k, v] = parsed;
        if (k.startsWith("GEMINI_EAP_") || /_API_KEY(_[A-Z0-9]+)?$/.test(k) || /_TOKEN$/.test(k)) {
          if (!out.has(k)) out.set(k, v);
    }
      }
    }
  } catch {
    /* keyring unavailable (headless/CI) — rely on file+env */
  }
  return out;
}

export interface KeypoolConfig {
  pools: Map<string, PoolConfig>;
  secrets: Map<string, string>;
}

// Port of herd-keypool.py's custom simple YAML parser (strict subset).

export function loadKeypoolConfig(
  poolsPath: string,
  secretsPath: string,
): KeypoolConfig {
  const raw = parseSimpleYaml(readFileSync(poolsPath, "utf8"));
  const poolsRaw = raw["pools"] as Record<string, PoolConfig> | undefined;
  if (!poolsRaw || typeof poolsRaw !== "object" || Array.isArray(poolsRaw)) {
    throw new Error(`keypool: no 'pools' map in ${poolsPath}`);
  }
  const secrets = loadSecrets(secretsPath);
  const pools = new Map<string, PoolConfig>();
  for (const [name, cfg] of Object.entries(poolsRaw)) {
    if (!cfg || typeof cfg !== "object")
      throw new Error(`keypool '${name}': invalid config`);
    if (!cfg.upstream) throw new Error(`keypool '${name}': missing upstream`);
    if (!Array.isArray(cfg.keys) || cfg.keys.length === 0)
      throw new Error(`keypool '${name}': no keys configured`);
    // cooldown.default -> cooldown_default
    const cd = (cfg as unknown as Record<string, unknown>)["cooldown"] as
      Record<string, number> | undefined;
    if (cd && typeof cd === "object" && "default" in cd) {
      cfg.cooldown_default = cd["default"];
      delete cd["default"];
    }
    pools.set(name, cfg);
  }
  return { pools, secrets };
}

import { describe, expect, test } from "bun:test";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadSecrets } from "../src/config.js";

function withFile(content: string): () => string {
  const dir = mkdtempSync(join(tmpdir(), "kp-test-"));
  const p = join(dir, "secrets");
  writeFileSync(p, content);
  return () => p;
}

describe("loadSecrets secretsmith env contract", () => {
  test("strips single-quoted export values from `secretsmith env` output", () => {
    const f = withFile(
      `export OPENROUTER_API_KEY='sk-or-clean-key'\nexport NIM_API_KEY_1='nvapi-clean'\n`,
    );
    // secretsmith env emits shell exports: KEY='value' — the stored secret
    // must NOT carry the literal quotes, else Bearer headers become
    // `sk-...'` and every upstream 401s (the 2026-10-26 mass-down).
    const m = loadSecrets(f());
    expect(m.get("OPENROUTER_API_KEY")).toBe("sk-or-clean-key");
    expect(m.get("NIM_API_KEY_1")).toBe("nvapi-clean");
  });

  test("strips double quotes too", () => {
    const f = withFile(`GEMINI_EAP_KEY_1="dq-value"\nPLAIN=no-quotes\n`);
    const m = loadSecrets(f());
    expect(m.get("GEMINI_EAP_KEY_1")).toBe("dq-value");
    expect(m.get("PLAIN")).toBe("no-quotes");
  });

  test("leaves a quote inside the value alone (only matching pairs strip)", () => {
    const f = withFile(`A='has "inside"'\nB="it's fine"\n`);
    const m = loadSecrets(f());
    expect(m.get("A")).toBe('has "inside"');
    expect(m.get("B")).toBe("it's fine");
  });
});

// Eval-kernel secrets preload — WINNER: technique B (in-process D-Bus via
// python3 secretstorage). Loads ALL keyring items into process.env ONCE at
// kernel boot; zero per-command transport afterwards (no secretsmith spawns).
//
// Race results (2026-10-29):
//   A) subprocess `secretsmith search '' --json --show` : 295ms dump, but
//      secret_preview is MASKED — full secrets need per-label gets = N
//      subprocess spawns per read. Loses on transport count.
//   C) `secretsmith env --app <app>` : BROKEN (0 vars) — anomaly #19 emitter-skip.
//   B) in-process D-Bus (secretstorage) : 173 items in 1.65s, FULL secrets,
//      ZERO per-command transport. WINNER.
//
// Gotcha found: `secretsmith get THRESHER_API_KEY --show` returns junk
// ("label:" YAML blob, 221 chars) while the D-Bus item is correct (64 chars) —
// same item, two truths. D-Bus is ground truth; secretsmith's read path is
// the buggy half (anomaly #19 class). Never trust secretsmith -show for
// verification; read via D-Bus.
//
// Usage: %load <this file> at kernel start (or run once; state persists
// across compaction). Kernel loss -> re-run this cell.

const { spawnSync } = await import("node:child_process");

const PRELOAD_SCRIPT = `
import secretstorage, os, sys

def main():
    try:
        conn = secretstorage.dbus_init()
    except Exception as e:
        print(f"DBUS_UNAVAILABLE: {e}", file=sys.stderr)
        return
    coll = secretstorage.get_default_collection(conn)
    loaded = 0
    for it in coll.get_all_items():
        try:
            lab = it.get_label()
        except Exception:
            continue
        if not lab or lab.startswith("label:") or "=" in lab:
            continue
        try:
            sec = it.get_secret()
        except Exception:
            continue
        if not sec:
            continue
        # valid env names only (the SSOT names are all uppercase snake)
        if not lab.replace("_", "").isalnum() or not lab.isupper():
            continue
        os.environ[lab] = sec.decode(errors="replace")
        loaded += 1
    print(f"loaded {loaded} items")
main()
`;

function dbusLoad() {
  const res = spawnSync("python3", ["-c", PRELOAD_SCRIPT], {
    encoding: "utf8",
    env: { ...process.env, PYTHONUNBUFFERED: "1" },
    timeout: 20_000,
  });
  if (res.status !== 0) {
    throw new Error(`keyring D-Bus preload failed: ${res.stderr || res.stdout}`);
  }
  return (res.stdout || "").trim();
}

// Idempotent: only run the D-Bus read once per kernel lifetime.
if (!globalThis.__KERNEL_SECRETS_LOADED__) {
  const t0 = performance.now();
  const msg = dbusLoad();
  globalThis.__KERNEL_SECRETS_LOADED__ = true;
  globalThis.__KERNEL_SECRETS_MS__ = Math.round(performance.now() - t0);
  console.log(`[kryptos-preload] ${msg} in ${globalThis.__KERNEL_SECRETS_MS__}ms (zero-transport D-Bus)`);
} else {
  console.log("[kryptos-preload] already loaded in this kernel lifetime");
}

// Prove: THRESHER_API_KEY present in process.env without any subprocess.
const k = process.env.THRESHER_API_KEY || "";
console.log(
  `[kryptos-preload] THRESHER_API_KEY ${k ? `OK len=${k.length} prefix=${k.slice(0, 6)}` : "MISSING"}`,
);

