    if as_json:
        print(
            json.dumps(
                {
                    "source": "secretservice",
                    "item": a.id_or_name,
                    "value": val if a.show else redact(len(val)),
                }
            )
        )
    else:
        print(val if a.show else redact(len(val)))
    return 0


