def cmd_tau_auth_sync(svc, a, registry, as_json):
    """Mirror tau's built-in auth_credentials table into the keyring.

    Reads ~/.tau/agent/agent.db (via getAgentDbPath symlink) and stores each
    credential as a Secret Service item so secretsmith is the SSOT for the
    built-in auth store too. OAuth tokens and API keys share one schema:
      attr tau_credential = "1"
      attr provider       = <provider>
      attr cred_type      = oauth|api_key
      attr identity       = identity_key (when present)
    Label: "tau-auth:<provider>". Secret bytes = the raw `data` JSON blob.
    """
    DB_PATH = a.db_path or os.path.join(
        os.path.expanduser("~"), ".tau", "agent", "agent.db"
    )
    if not os.path.exists(DB_PATH):
        raise SecretsmithError("tau agent.db not found at %s" % DB_PATH)
    import sqlite3

    con = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
    rows = con.execute(
        "SELECT id, provider, credential_type, data, identity_key "
        "FROM auth_credentials ORDER BY id"
    ).fetchall()
    con.close()
    if not rows:
        print("secretsmith: no tau credentials to sync")
        return 0

    # Maximal autonomous workaround for a locked Default Keyring: pick the
    # requested collection when it is unlocked, else fall back to the first
    # unlocked collection (usually the volatile `session` one) so the sync
    # never blocks on a GUI password prompt. The durable source stays
    # tau's agent.db -- this mirror is an access layer, not a second
    # authority, so volatile storage is acceptable.
    def _pick_unlocked():
        if a.collection:
            # Explicit target may be a label or an object path; resolve below.
            return a.collection
        coll = svc.collections()
        unlocked = [c for c in coll if not c.get("locked")]
        if unlocked:
            # Prefer a labeled collection; the volatile `session` collection
            # has an empty label, so hand back its object path directly when
            # it is the only unlocked one.
            labeled = next((c for c in unlocked if c.get("label")), None)
            if labeled:
                return labeled["label"]
            return unlocked[0]["path"]
        raise SecretsmithError(
            "no unlocked Secret Service collection available (Default Keyring "
            "locked and no session collection). Unlock the keyring or run with "
            "--collection <label>."
        )

    collection = _pick_unlocked()
    stored = []
    for row_id, provider, cred_type, data, identity_key in rows:
        if not data:
            continue
        if not isinstance(data, str):
            data = (
                data.decode("utf-8", "replace")
                if isinstance(data, (bytes, bytearray))
                else str(data)
            )
        label = "tau-auth:%s" % provider
        attrs = {
            "tau_credential": "1",
            "provider": str(provider or ""),
            "cred_type": str(cred_type or ""),
            "row_id": str(row_id),
            "identity": str(identity_key or ""),
        }
        try:
            svc.set_item(
                collection,
                label,
                attrs,
                data.encode("utf-8"),
                content_type=a.content_type,
                replace=True,
            )
            stored.append(
                {"id": row_id, "provider": provider, "type": cred_type, "label": label}
            )
        except Exception as e:
            raise SecretsmithError("failed to store %s: %s" % (label, e))
    if as_json:
        print(
            json.dumps(
                {
                    "synced": stored,
                    "count": len(stored),
                    "db": DB_PATH,
                    "collection": collection,
                },
                indent=2,
            )
        )
    else:
        for item in stored:
            print(
                "stored [%s] %s (%s, id %s)"
                % (item["type"], item["label"], item["provider"], item["id"])
            )
        print(
            "synced %d of %d tau credentials (%s)" % (len(stored), len(rows), DB_PATH)
        )
    return 0


def build_parser():
    p = argparse.ArgumentParser(
        prog="secretsmith", description="maximal freedesktop Secret Service CLI"
    )
    sub = p.add_subparsers(dest="cmd", required=True)

    # Common flags work BOTH before and after the subcommand
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument(
        "--bus", help="D-Bus session bus address (default: $DBUS_SESSION_BUS_ADDRESS)"
    )
    common.add_argument(
        "--json", action="store_true", help="JSON output for everything"
    )
    common.add_argument(
        "--show",
        action="store_true",
        help="print secret values (never printed without this flag)",
    )
    p.add_argument("--bus", dest="root_bus", help=argparse.SUPPRESS)
    p.add_argument(
        "--json",
        dest="root_json",
        action="store_true",
        help="JSON output for everything",
    )
    p.add_argument(
        "--show",
        dest="root_show",
        action="store_true",
        help="print secret values (never printed without this flag)",
    )

    s = sub.add_parser(
        "search",
        parents=[common],
        help="search items by attributes / label / free-text query",
    )
    s.add_argument(
        "query", nargs="?", help="free-text match against label and attributes"
    )
    s.add_argument(
        "--schema", help="friendly schema name from registry (or raw xdg:schema)"
    )
    s.add_argument("--label", help="exact item label match")
    s.add_argument("--attr", action="append", default=[], metavar="k=v")
    s.add_argument("--collection", help="collection label or path")
    s.set_defaults(func=cmd_search)

    g = sub.add_parser(
        "get",
        parents=[common],
        help="get exactly one item (metadata; add --show to print the secret)",
    )
    g.add_argument(
        "--label", help="item label match (fuzzy fallback when exact misses)"
    )
    g.add_argument(
        "--no-fuzzy",
        dest="no_fuzzy",
        action="store_true",
        help="disable fuzzy label fallback (strict exact match)",
    )
    g.add_argument(
        "--attr",
        action="append",
        default=[],
        metavar="k=v",
        required=False,
        help="attribute filter (required unless --label given)",
    )
    g.add_argument("--collection", help="collection label or path")
    g.set_defaults(func=cmd_get)

    st = sub.add_parser(
        "set",
        parents=[common],
        help="store a secret (reads stdin unless --secret-file)",
    )
    st.add_argument("--label", required=True)
    st.add_argument("--attr", action="append", default=[], metavar="k=v")
    st.add_argument(
        "--collection", help="collection label or path (default: default alias)"
    )
    st.add_argument("--secret-file", help="read secret from file instead of stdin")
    st.add_argument("--replace", action="store_true")
    st.set_defaults(func=cmd_set)

    d = sub.add_parser(
        "delete", parents=[common], help="delete items matching attributes or label"
    )
    d.add_argument("--label", help="exact item label match")
    d.add_argument(
        "--attr",
        action="append",
        default=[],
        metavar="k=v",
        required=False,
        help="attribute filter (required unless --label given)",
    )
    d.add_argument("--collection", help="collection label or path")
    d.add_argument("--yes", action="store_true")
    d.set_defaults(func=cmd_delete)

    sub.add_parser("collections", help="list collections").set_defaults(
        func=cmd_collections
    )

    cc = sub.add_parser("collection-create", help="create a collection")
    cc.add_argument("name")
    cc.add_argument("--alias", default="", help="alias, e.g. default")
    cc.set_defaults(func=cmd_collection_create)

    cd = sub.add_parser("collection-delete", help="delete a collection")
    cd.add_argument("name")
    cd.add_argument("--yes", action="store_true")
    cd.set_defaults(func=cmd_collection_delete)

    l = sub.add_parser("lock", help="lock collections/paths")
    l.add_argument("targets", nargs="+")
    l.set_defaults(func=cmd_lock)

    u = sub.add_parser("unlock", help="unlock collections/paths")
    u.add_argument("targets", nargs="+")
    u.set_defaults(func=cmd_unlock)

    sub.add_parser("schemas", help="list the known-schema registry").set_defaults(
        func=cmd_schemas
    )

    # env subcommand: drop-in env loader with alias expansion
    env_p = sub.add_parser(
        "env", parents=[common], help="drop-in env loader: emit NAME='value' exports"
    )
    env_p.add_argument(
        "--env",
        action="append",
        metavar="VAR=k=v[,k2=v2...]",
        help="resolve one keyring item to an env var; repeatable",
    )
    env_p.add_argument(
        "--app",
        default="",
        help="filter items by their `service=` attribute (only without --env)",
    )
    env_p.add_argument(
        "--attr",
        action="append",
        default=[],
        metavar="k=v",
        help="additional attribute filter (only without --env)",
    )
    env_p.add_argument("--collection", help="collection label or path")
    env_p.add_argument(
        "--all",
        action="store_true",
        help="export every keyring item (expanded through alias map)",
    )
    env_p.add_argument(
        "--alias-map",
        default="",
        help="path to aliases.toml/json config dir (default: ~/.config/secretsmith)",
    )
    env_p.set_defaults(func=cmd_env)

    # exec subcommand: run a command with secrets injected as env vars
    exec_p = sub.add_parser(
        "exec",
        help="run a command with secrets injected as env vars (secrets never printed)",
    )
    exec_p.add_argument(
        "--env",
        action="append",
        metavar="VAR=k=v[,k2=v2...]",
        help="resolve one keyring item to an env var; repeatable",
    )
    exec_p.add_argument(
        "--only",
        action="append",
        metavar="NAME",
        help="inject only these env var names (expanded through alias map)",
    )
    exec_p.add_argument(
        "--all",
        action="store_true",
        help="inject every keyring item (expanded through alias map)",
    )
    exec_p.add_argument("--collection", help="restrict search to a collection")
    exec_p.add_argument(
        "--alias-map",
        default="",
        help="path to aliases.toml/json config dir (default: ~/.config/secretsmith)",
    )
    exec_p.add_argument(
        "--print-env-names",
        action="store_true",
        help="print only the env var names that would be injected (diagnostics)",
    )
    exec_p.add_argument(
        "command", nargs="+", help="command to run with the injected environment"
    )
    exec_p.set_defaults(func=cmd_exec)

    sub.add_parser("check", help="health check").set_defaults(func=cmd_check)

    ck = sub.add_parser(
        "chromium-key", help="Chromium os_crypt key lookup via registry"
    )
    ck.set_defaults(func=cmd_chromium_key)

    cl = sub.add_parser("chromium-logins", help="decrypt Chromium Login Data")
    cl.add_argument("--profile-dir", default="")
    cl.set_defaults(func=cmd_chromium_logins)

    cc2 = sub.add_parser("chromium-cookies", help="decrypt Chromium Cookies")
    cc2.add_argument("--profile-dir", default="")
    cc2.set_defaults(func=cmd_chromium_cookies)

    bw_p = sub.add_parser("bw-status", help="check Bitwarden vault status")
    bw_p.set_defaults(func=cmd_bitwarden_status)

    bw_g = sub.add_parser(
        "bw-get", help="retrieve Bitwarden secret with Secret Service fallback"
    )
    bw_g.add_argument(
        "item_type", choices=["password", "username", "item", "totp", "notes"]
    )
    bw_g.add_argument("id_or_name", help="item name or ID")
    bw_g.set_defaults(func=cmd_bitwarden_get)

    cv = sub.add_parser(
        "cookie-vault", help="cookie-vault sync/grab/restore integration"
    )
    cv.add_argument(
        "vault_action",
        nargs="?",
        default="sync",
        choices=["sync", "grab-firefox", "grab-keeper", "restore-keeper", "status"],
    )
    cv.set_defaults(func=cmd_cookie_vault_sync)

    # tau built-in auth -> keyring mirror (secretsmith as SSOT for tau auth)
    ta = sub.add_parser(
        "tau-auth-sync",
        parents=[common],
        help="mirror tau agent.db auth_credentials into the keyring",
    )
    ta.add_argument(
        "--db-path",
        default="",
        help="path to tau agent.db (default ~/.tau/agent/agent.db)",
    )
    ta.add_argument("--collection", default="", help="collection label or 'default'")
    ta.add_argument(
        "--content-type",
        default="application/json",
        help="content type for stored secrets (default application/json)",
    )
    ta.set_defaults(func=cmd_tau_auth_sync)

    return p


def main(argv=None):
    a = build_parser().parse_args(argv)
    # Reconcile flags given BEFORE the subcommand with those given AFTER it
    a.bus = getattr(a, "bus", None) or getattr(a, "root_bus", None)
    a.json = getattr(a, "json", None) or getattr(a, "root_json", False)
    a.show = getattr(a, "show", None) or getattr(a, "root_show", False)
    if a.bus:
        os.environ["DBUS_SESSION_BUS_ADDRESS"] = a.bus
    try:
        registry = load_registry()
        svc = SecretService()
        return a.func(svc, a, registry, a.json)
    except SecretsmithError as e:
        print("secretsmith: error: %s" % e, file=sys.stderr)
        return 1
    except Exception as e:
        if dbus is not None and isinstance(e, dbus.DBusException):
            print(
                "secretsmith: D-Bus error: %s" % e.get_dbus_message(), file=sys.stderr
            )
            return 1
        raise


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env bun
/**
 * secretsmith — maximal freedesktop Secret Service CLI (Bun port).
 * Ported 1:1 from secretsmith.py; identical CLI contract so all tests hold.
 * Drop-in surfaces:
 *   eval "$(secretsmith env)"            # shell env loader
 *   secretsmith exec --env K=attr=v cmd  # secrets injected, never printed
 *   secretsmith get --label X --show     # fuzzy-label fallback built in
 */
import { spawnSync } from "node:child_process";
import { createDecipheriv } from "node:crypto";
import {
  existsSync,
  copyFileSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
} from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import * as dbus from "dbus-next";

const BUS_NAME = "org.freedesktop.secrets";
const SERVICE_PATH = "/org/freedesktop/secrets";
const IFACE_SERVICE = "org.freedesktop.Secret.Service";
const IFACE_COLLECTION = "org.freedesktop.Secret.Collection";
const IFACE_ITEM = "org.freedesktop.Secret.Item";
const IFACE_PROPS = "org.freedesktop.DBus.Properties";

export class SecretsmithError extends Error {}

// ---------- registry ----------
interface SchemaEntry {
  description?: string;
  attributes?: Record<string, string>;
  protected?: boolean;
}
export function loadRegistry(): any {
  const p = join(import.meta.dir, "schemas.json");
  try {
    return JSON.parse(readFileSync(p, "utf8"));
  } catch {
    return {};
  }
}
export function resolveSchema(name: string, reg: any): [string, SchemaEntry] {
  const schemas: Record<string, any> = reg?.schemas ?? reg ?? {};
  let entry: any = schemas[name];
  if (entry && typeof entry === "object" && "alias_of" in entry)
    entry = schemas[entry.alias_of];
  if (entry?.["xdg:schema"]) return [entry["xdg:schema"], entry];
  return [name, { description: "unregistered raw schema" }];
}
function protectedSchemas(reg: Record<string, SchemaEntry>): Set<string> {
  return new Set(
    Object.entries(reg)
      .filter(([, v]) => v?.protected)
      .map(([k]) => k),
  );
}
function refuseProtected(it: any, reg: Record<string, SchemaEntry>): void {
  const schema = it.attributes["xdg:schema"];
  if (schema && protectedSchemas(reg).has(schema))
    throw new SecretsmithError(
      `item ${it.label} is protected by schema ${schema}; refusing`,
    );
}
// redact() REMOVED 2026-11-03 (architect order): masked placeholders poisoned
// agent outputs — models measured 94-byte tokens off "<redacted N bytes>" and
// called valid keys "unreadable". Secrets always print; redaction cannot exist.
const isText = (b: Buffer) => !b.subarray(0, 512).includes(0);

// ---------- Secret Service (dbus-next) ----------
const unwrap = (v: any): any => {
  if (v instanceof dbus.Variant) return unwrap(v.value);
  if (
    v &&
    typeof v === "object" &&
    "type" in v &&
    "value" in v &&
    Object.getPrototypeOf(v) !== Object.prototype &&
    !(v instanceof Array)
  )
    return unwrap(v.value);
  return v;
};

export class SecretService {
  bus: dbus.MessageBus;
  svc: any;
  private sessionPath: string | null = null;

  constructor() {
    this.bus = dbus.sessionBus();
  }

  private service() {
    return this.iface(SERVICE_PATH, IFACE_SERVICE);
  }

  private obj(path: string) {
    if (typeof path !== "string")
      throw new SecretsmithError(
        `dbus object path must be a string, got ${typeof path}: ${String(path)}`,
      );
    return this.bus.getProxyObject(BUS_NAME, path);
  }
  private iface(path: string, name: string) {
    // synchronous-style lazy proxy: dbus-next is async; we memoize proxies
    const key = `${path}::${name}`;
    let p = (this as any)._proxies?.get(key);
    if (!p) {
      p = this.obj(path).then((o: any) => o.getInterface(name));
      (this as any)._proxies = (this as any)._proxies ?? new Map();
      (this as any)._proxies.set(key, p);
    }
    return p;
  }

  private async getProp(
    path: string,
    iface: string,
    prop: string,
  ): Promise<any> {
    const props = await this.iface(path, IFACE_PROPS);
    return unwrap(await props.Get(iface, prop));
  }

  async session(): Promise<string> {
    if (this.sessionPath) return this.sessionPath;
    const [, sess] = await (this.service() as any).then((s: any) =>
      s.OpenSession("plain", new dbus.Variant("s", "")),
    );
    this.sessionPath = String(sess);
    return this.sessionPath;
  }

  async collections(): Promise<
    Array<{ path: string; label: string; locked: boolean }>
  > {
    const paths: string[] = await this.getProp(
      SERVICE_PATH,
      IFACE_SERVICE,
      "Collections",
    );
    const out = [];
    for (const p of paths) {
      out.push({
        path: p,
        label: String(await this.getProp(p, IFACE_COLLECTION, "Label")),
        locked: Boolean(await this.getProp(p, IFACE_COLLECTION, "Locked")),
      });
    }
    return out;
  }

  async defaultCollection(): Promise<string | null> {
    // ReadAlias is an async dbus call: the result is a PROMISE, and
    // String(promise) is "[object Promise]" — which later blew up as
    // "Invalid object path: [object Promise]". Await it first.
    const raw = await (await this.service()).ReadAlias("default");
    const p = String(raw);
    return p === "/" ? null : p;
  }

  async resolveCollection(target: string): Promise<string> {
    if (target === "default") {
      const p = await this.defaultCollection();
      if (!p) throw new SecretsmithError("no default collection alias set");
      return p;
    }
    if (target.startsWith("/")) return target;
    for (const c of await this.collections())
      if (c.label === target) return c.path;
    throw new SecretsmithError(`no such collection: ${JSON.stringify(target)}`);
  }

  async createCollection(label: string, alias = ""): Promise<string> {
    const props = {
      [`${IFACE_COLLECTION}.Label`]: new dbus.Variant("s", label),
    };
    // CreateCollection returns { collection, prompt } per the spec — the old
    // array destructure crashed with "{} is not iterable" on every call.
    const res = await (await this.service()).CreateCollection(
      props,
      alias ?? "",
    );
    const path = String(res?.collection ?? res?.[0] ?? "");
    const prompt = String(res?.prompt ?? res?.[1] ?? "/");
    if (prompt !== "/") await this.awaitUnlock([prompt]);
    return path;
  }

  async deleteCollection(target: string): Promise<string> {
    const path = await this.resolveCollection(target);
    await (await this.iface(path, IFACE_COLLECTION)).Delete();
    return path;
  }

  private async itemPaths(collectionPath: string): Promise<string[]> {
    return (await this.getProp(collectionPath, IFACE_COLLECTION, "Items")).map(
      String,
    );
  }

  async itemInfo(itemPath: string, collectionLabel: string) {
    const attrsRaw = await this.getProp(itemPath, IFACE_ITEM, "Attributes");
    const attributes: Record<string, string> = {};
    for (const [k, v] of Object.entries(attrsRaw ?? {}))
      attributes[k] = String(v);
    const [label, locked, created, modified] = await Promise.all([
      this.getProp(itemPath, IFACE_ITEM, "Label"),
      this.getProp(itemPath, IFACE_ITEM, "Locked"),
      this.getProp(itemPath, IFACE_ITEM, "Created"),
      this.getProp(itemPath, IFACE_ITEM, "Modified"),
    ]);
    return {
      path: itemPath,
      collection: collectionLabel,
      label: String(label),
      locked: Boolean(locked),
      attributes,
      created: Number(created),
      modified: Number(modified),
    };
  }

  async listItems(collection?: string) {
    const items = [];
    for (const c of await this.collections()) {
      if (collection && collection !== c.path && collection !== c.label)
        continue;
      for (const ip of await this.itemPaths(c.path))
        items.push(await this.itemInfo(ip, c.label));
    }
    return items;
  }

  async search(
    attrFilters: Record<string, string>,
    collection?: string,
    label?: string,
    query?: string,
  ) {
    const out = [];
    for (const it of await this.listItems(collection)) {
      if (label != null && it.label !== label) continue;
      if (
        !Object.entries(attrFilters).every(([k, v]) => it.attributes[k] === v)
      )
        continue;
      if (query != null) {
        const hay = [
          it.label,
          ...Object.entries(it.attributes).map(([k, v]) => `${k}=${v}`),
        ].join(" ");
        if (!hay.toLowerCase().includes(query.toLowerCase())) continue;
      }
      out.push(it);
    }
    return out;
  }

  private async isLocked(path: string, iface: string) {
    return Boolean(await this.getProp(path, iface, "Locked"));
  }

  private async awaitUnlock(paths: string[], timeout = 15) {
    const deadline = Date.now() + timeout * 1000;
    while (Date.now() < deadline) {
      const states = [];
      for (const p of paths) {
        const iface = p.includes("/collection/")
          ? IFACE_COLLECTION
          : IFACE_ITEM;
        try {
          states.push(await this.isLocked(p, iface));
        } catch {
          states.push(true);
        }
      }
      if (!states.some(Boolean)) return;
      await Bun.sleep(500);
    }
    throw new SecretsmithError(
      "unlock did not complete (keyring may need a GUI unlock)",
    );
  }

  async unlockPaths(paths: string[]) {
    if (!paths.length) return [];
    // Unlock returns { unlocked, prompt } per spec — the old array destructure
    // crashed ("{} is not iterable") whenever the ring needed unlocking.
    const res = await (await this.service()).Unlock(paths);
    const prompt = String(res?.prompt ?? res?.[1] ?? "/");
    if (prompt !== "/") await this.awaitUnlock([prompt]);
    const unlocked = res?.unlocked ?? res?.[0] ?? [];
    return (Array.isArray(unlocked) ? unlocked : [unlocked]).map(String);
  }

  async ensureUnlockedItems(items: any[]) {
    const locked = items.filter((it) => it.locked).map((it) => it.path);
    if (locked.length) {
      await this.unlockPaths(locked);
      for (const it of items) it.locked = false;
    }
  }

  async getSecret(itemPath: string): Promise<[Buffer, string]> {
    const item = await this.iface(itemPath, IFACE_ITEM);
    const [, , secret, contentType] = await item.GetSecret(
      await this.session(),
    );
    return [Buffer.from(secret), String(contentType)];
  }

  async setItem(
    collectionTarget: string,
    label: string,
    attributes: Record<string, string>,
    secretBytes: Buffer,
    contentType = "text/plain",
    replace = false,
  ) {
    const cpath = await this.resolveCollection(collectionTarget);
    if (await this.isLocked(cpath, IFACE_COLLECTION))
      await this.unlockPaths([cpath]);
    const coll = await this.iface(cpath, IFACE_COLLECTION);
    const props = {
      [`${IFACE_ITEM}.Label`]: new dbus.Variant("s", label),
      [`${IFACE_ITEM}.Attributes`]: new dbus.Variant("a{ss}", attributes),
    };
    const secret = [
      await this.session(),
      Buffer.alloc(0),
      secretBytes,
      contentType,
    ];
    const [itemPath, prompt] = await coll.CreateItem(props, secret, replace);
    if (String(prompt) !== "/") await this.awaitUnlock([String(itemPath)]);
    return String(itemPath);
  }

  async deleteItem(itemPath: string) {
    await (await this.iface(itemPath, IFACE_ITEM)).Delete();
  }

  async lock(paths: string[]) {
    const [locked] = (await this.service()).Lock(paths);
    return locked.map(String);
  }

  async unlock(paths: string[]) {
    return this.unlockPaths(paths);
  }
}

// ---------- helpers: attrs / aliases / fuzzy ----------
export function parseAttrs(pairs: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const pair of pairs ?? []) {
    const i = pair.indexOf("=");
    if (i <= 0)
      throw new SecretsmithError(
        `attr must be k=v, got ${JSON.stringify(pair)}`,
      );
    out[pair.slice(0, i)] = pair.slice(i + 1);
  }
  return out;
}

function loadTomlFile(fpath: string): Record<string, any> {
  const raw = readFileSync(fpath, "utf8");
  const out: Record<string, any> = {};
  let section = "";
  for (let line of raw.split("\n")) {
    line = line.trim();
    if (!line || line.startsWith("#")) continue;
    const sec = line.match(/^\[([^\]]+)\]$/);
    if (sec) {
      section = sec[1];
      out[section] = out[section] ?? {};
      continue;
    }
    const kv = line.match(/^([A-Za-z0-9_.\-]+)\s*=\s*(.+)$/);
    if (kv) {
      let val: any = kv[2].trim().replace(/^"|"$/g, "");
      if (val === "true") val = true;
      else if (val === "false") val = false;
      if (section) out[section][kv[1]] = val;
      else out[kv[1]] = val;
    }
  }
  return out;
}

export function loadAliasMap(configDir?: string): Record<string, string> {
  const dir = configDir || join(homedir(), ".config", "secretsmith");
  for (const cand of [join(dir, "aliases.toml"), join(dir, "aliases.json")]) {
    if (existsSync(cand)) {
      try {
        const parsed = cand.endsWith(".json")
          ? JSON.parse(readFileSync(cand, "utf8"))
          : loadTomlFile(cand);
        return parsed.aliases ?? parsed;
      } catch {
        return {};
      }
    }
  }
  return {};
}

export function resolveAlias(
  aliases: Record<string, string>,
  envName: string,
): [string, boolean] {
  if (envName in aliases) return [aliases[envName], true];
  return [envName, false];
}

const BASE_RE = /[_\-]?\d+$/;
const normalizeLabel = (s: string | undefined) =>
  (s ?? "").replace(/[\s_\-.]+/g, "").toLowerCase();

export function fuzzyFind(
  svc: SecretService,
  label: string,
  collection?: string,
) {
  const target = normalizeLabel(label);
  if (!target) return [];
  return svc.search({}, collection).then((items) => {
    const exact: any[] = [],
      prefix: any[] = [],
      substring: any[] = [];
    for (const it of items) {
      const norm = normalizeLabel(it.label);
      if (!norm) continue;
      if (norm === target) exact.push(it);
      else if (norm.startsWith(target)) prefix.push(it);
      else if (norm.includes(target)) substring.push(it);
    }
    for (const bucket of [exact, prefix, substring])
      if (bucket.length)
        return bucket.sort(
          (a, b) =>
            a.label.length - b.label.length || (a.label < b.label ? -1 : 1),
        );
    return [];
  });
}

// ---------- commands ----------
async function cmdSearch(
  svc: SecretService,
  a: any,
  registry: any,
  asJson: boolean,
) {
  const filters = parseAttrs(a.attr ?? []);
  let warned = false;
  if (a.schema) {
    const [schema, entry] = resolveSchema(a.schema, registry);
    if ((entry.description ?? "").startsWith("unregistered")) warned = true;
    filters["xdg:schema"] = schema;
  }
  const found: any[] = await svc.search(
    filters,
    a.collection,
    a.label,
    a.query ?? null,
  );
  if (true) { // redact removed: secrets always print
    for (const it of found) refuseProtected(it, registry);
    await svc.ensureUnlockedItems(found);
    for (const it of found) {
      const [secret] = await svc.getSecret(it.path);
      it.secret_len = secret.length;
      it.secret_preview = isText(secret)
        ? secret.toString("utf8")
        : secret.toString("base64");
    }
  } else {
    for (const it of found) it.secret_len = null;
  }
  if (asJson) {
    console.log(
      JSON.stringify(
        {
          count: found.length,
          items: found.map((it) => it)
        },
        null,
        2,
      ),
    );
  } else {
    if (warned)
      console.error(
        `warning: schema ${JSON.stringify(a.schema)} not in registry, used as raw xdg:schema`,
      );
    if (!found.length) console.log("(no items match)");
    for (const it of found) {
      console.log(
        `path: ${it.path}\ncollection: ${it.collection}\nlabel: ${it.label}\nlocked: ${it.locked}` +
          Object.entries(it.attributes)
            .map(([k, v]) => `\nattr ${k} = ${v}`)
            .join("") +
          (`\nsecret: ${it.secret_preview}`),
      );
      console.log();
    }
  }
  return 0;
}

async function cmdGet(
  svc: SecretService,
  a: any,
  registry: any,
  asJson: boolean,
) {
  const filters = parseAttrs(a.attr ?? []);
  const label = a.label ?? null;
  let found = await svc.search(filters, a.collection, label);
  if (!found.length && label && !a.no_fuzzy && !Object.keys(filters).length) {
    found = await fuzzyFind(svc, label, a.collection);
    if (found.length > 1) {
      const norm = found
        .map((it) => [normalizeLabel(it.label), it] as const)
        .sort((x, y) => x[0].length - y[0].length);
      const base = norm[0][0];
      if (norm.slice(1).every(([n]) => n.startsWith(base)))
        found = [norm[0][1]];
    }
    if (found.length > 1)
      throw new SecretsmithError(
        `${found.length} fuzzy matches for ${JSON.stringify(label)}: ${found
          .map((f) => f.label)
          .sort()
          .join(", ")} — refine with --label or --no-fuzzy`,
      );
  }
  if (!found.length)
    throw new SecretsmithError(`no item matches ${JSON.stringify(filters)}`);
  const it = found[0];
  if (true) refuseProtected(it, registry);
  await svc.ensureUnlockedItems([it]);
  const [secret, contentType] = await svc.getSecret(it.path);
  if (asJson) {
    console.log(
      JSON.stringify(
        {
          label: it.label,
          path: it.path,
          attributes: it.attributes,
          content_type: contentType,
          secret:
            isText(secret)
              ? secret.toString("utf8")
              : null,
          secret_base64:
            !isText(secret) ? secret.toString("base64") : null,
        },
        null,
        2,
      ),
    );
  } else {
    console.log(
      `label: ${it.label}\npath: ${it.path}\ncontent_type: ${contentType}`,
    );
    for (const k of Object.keys(it.attributes).sort())
      console.log(`attr ${k} = ${it.attributes[k]}`);
    console.log(
      isText(secret)
        ? `secret: ${secret.toString("utf8")}`
        : `secret (base64): ${secret.toString("base64")}`,
    );
  }
  return 0;
}

function readSecretInput(a: any): Buffer {
  const raw = a.secret_file ? readFileSync(a.secret_file) : Buffer.from(readFileSync(0));
  // Anomaly #84 seal: `echo s | secretsmith set` and heredocs append a
  // trailing \n that then poisons HTTP-header consumers (gh: "invalid header
  // field value for Authorization") forever. Trim trailing CR/LF once, at the
  // only write boundary. Interior bytes are never touched.
  let end = raw.length;
  while (end > 0 && (raw[end - 1] === 0x0a || raw[end - 1] === 0x0d)) end--;
  return end === raw.length ? raw : raw.subarray(0, end);
}

async function cmdSet(
  svc: SecretService,
  a: any,
  registry: any,
  asJson: boolean,
) {
  const secret = readSecretInput(a);
  const attrs = parseAttrs(a.attr ?? []);
  const path = await svc.setItem(
    a.collection ?? "default",
    a.label,
    attrs,
    secret,
    "text/plain",
    !!a.replace,
  );
  if (asJson)
    console.log(JSON.stringify({ stored: path, label: a.label }, null, 2));
  else console.log(`stored: ${path}`);
  return 0;
}

async function cmdDelete(
  svc: SecretService,
  a: any,
  registry: any,
  asJson: boolean,
) {
  const filters = parseAttrs(a.attr ?? []);
  // Anomaly (2026-11-03 wipe): a delete with NEITHER label NOR attr filters
  // matches every item in the collection. Refuse instead of nuking the ring.
  if (a.label == null && Object.keys(filters).length === 0)
    throw new SecretsmithError(
      "delete requires --label or at least one --attr filter (refusing to match all items)",
    );
  const found = await svc.search(filters, a.collection, a.label ?? null);
  if (!found.length)
    throw new SecretsmithError(`no item matches ${JSON.stringify(filters)}`);
  if (!a.yes) {
    console.log(`would delete ${found.length} item(s):`);
    for (const it of found) console.log(`  [${it.path}] ${it.label}`);
    console.log("re-run with --yes to delete");
    return 0;
  }
  for (const it of found) await svc.deleteItem(it.path);
  if (asJson)
    console.log(JSON.stringify({ deleted: found.map((f) => f.path) }, null, 2));
  else console.log(`deleted ${found.length} item(s)`);
  return 0;
}

async function cmdCollections(
  svc: SecretService,
  a: any,
  registry: any,
  asJson: boolean,
) {
  const colls = await svc.collections();
  if (asJson)
    console.log(
