async function resolveTargets(
  svc: SecretService,
  targets: string[],
  kind: "collection" | "any",
) {
  const paths: string[] = [];
  for (const t of targets) {
    if (t.startsWith("/")) paths.push(t);
    else if (
      kind === "any" &&
      (t.includes("/collection/") || t.includes("/item/"))
    )
      paths.push(t);
    else paths.push(await svc.resolveCollection(t));
  }
  return paths;
}

