          key_candidates: cands.length,
          keys_hex: cands.map((c) => c.toString("hex")),
        },
        null,
        2,
      ),
    );
  else {
    console.log(
      `label: ${item.label}\nsecret bytes: ${secret.length}\nkey candidates: ${cands.length}`,
    );
    for (const c of cands) console.log(`  ${c.toString("hex")}`);
  }
  return 0;
}

