// TDD: `secretsmith delete <POSITIONAL_LABEL>` must resolve the positional as
// a label — not silently drop it and fall back to filters-only matching.
//
// Live bug (2026-11-03 ring wipe): the positional-label block lived only in
// the `get` case, so `secretsmith delete _SMOKE --yes` ran with
// a.label === undefined; cmdDelete's svc.search(filters, collection, null)
// then matched EVERY item and wiped the whole ring (209 items).
// Second anomaly the same day: `delete --attr app=x --yes` with the
// positional dropped matched every seeded item sharing that attr.
//
// Contracts pinned here:
// 1. delete positional label is captured (parity with get, anomaly #61).
// 2. cmdDelete refuses to run with NEITHER label NOR attr filters — a
//    filters-only match-all delete is structurally forbidden.
import { describe, test, expect } from "bun:test";
import { parse } from "../secretsmith.ts";

describe("secretsmith delete positional label (ring-wipe regression)", () => {
	test("delete with bare positional sets label", () => {
		const a = parse(["delete", "SOME_LABEL"]);
		expect(a.label).toBe("SOME_LABEL");
	});

	test("delete positional + --yes does not swallow the positional", () => {
		const a = parse(["delete", "SOME_LABEL", "--yes"]);
		expect(a.label).toBe("SOME_LABEL");
		expect(a.yes).toBe(true);
	});

	test("delete with --label flag still sets label", () => {
		const a = parse(["delete", "--label", "EXPLICIT"]);
		expect(a.label).toBe("EXPLICIT");
	});

	test("delete with both positional and --label: explicit flag wins", () => {
		const a = parse(["delete", "POSITIONAL", "--label", "EXPLICIT"]);
		expect(a.label).toBe("EXPLICIT");
	});

	test("delete attr-only keeps label undefined", () => {
		const a = parse(["delete", "--attr", "app=env-seed"]);
		expect(a.label).toBeUndefined();
		expect(a.attr).toEqual(["app=env-seed"]);
	});
});

// TDD: `secretsmith get <POSITIONAL_LABEL>` must resolve the positional as a
// label — not silently drop it and return an arbitrary first item.
// Live bug: `secretsmith get GITHUB_SESSIONS --json` returned
// MOONBOX_CHAOS_API_KEY (arbitrary first keyring item) because `case "get"`
// parsed no positional.
import { describe, test, expect } from "bun:test";
import { parse } from "../secretsmith.ts";

describe("secretsmith get positional label", () => {
	test("get with bare positional sets label", () => {
		const a = parse(["get", "GITHUB_SESSIONS"]);
		expect(a.label).toBe("GITHUB_SESSIONS");
	});

	test("get with positional + --json does not swallow the positional", () => {
		const a = parse(["get", "GITHUB_SESSIONS", "--json"]);
		expect(a.label).toBe("GITHUB_SESSIONS");
		expect(a.json).toBe(true);
	});

	test("get with --label flag still wins over positional absence", () => {
		const a = parse(["get", "--label", "EXPLICIT"]);
		expect(a.label).toBe("EXPLICIT");
	});

	test("get with both positional and --label: explicit flag wins", () => {
		const a = parse(["get", "POSITIONAL", "--label", "EXPLICIT"]);
		expect(a.label).toBe("EXPLICIT");
	});

	test("get with no label at all: label stays undefined (attr-only get)", () => {
		const a = parse(["get", "--attr", "service=app"]);
		expect(a.label).toBeUndefined();
	});

	test("get with missing label errors — never returns an arbitrary item (anomaly 63)", async () => {
		const missing = "MISSING_LABEL_" + Date.now();
		// Live CLI contract, not parse-shape: a nonexistent label MUST error.
		const proc = Bun.spawn(["bun", "secretsmith.ts", "get", missing], {
			cwd: import.meta.dir + "/..",
			stdout: "pipe",
			stderr: "pipe",
		});
		const stdout = await Bun.readableStreamToText(proc.stdout);
		const stderr = await Bun.readableStreamToText(proc.stderr);
		const exit = await proc.exited;
		// Contract: a missing label MUST error (never return an arbitrary first
		// item — the anomaly-63 defect). The error text need not echo the label.
		expect(stderr).toContain("no item matches");
		expect(stdout).toBe("");
		expect(exit).not.toBe(0);
	});

	test("get label-echo: returned item echoes the EXACT requested label", async () => {
		// The label is the key contract — a fuzzy/wrong fetch is the defect.
		const proc = Bun.spawn(["bun", "secretsmith.ts", "get", "GITHUB_TOKEN"], {
			cwd: import.meta.dir + "/..",
			stdout: "pipe",
			stderr: "pipe",
		});
		const stdout = await Bun.readableStreamToText(proc.stdout);
		const exit = await proc.exited;
		expect(exit).toBe(0);
		expect(stdout).toContain("label: GITHUB_TOKEN");
	});
});

import { describe, expect, test } from "bun:test";
import { execSync } from "node:child_process";
import { createCipheriv } from "node:crypto";
import {
  decryptChromiumBlob,
  keyCandidates,
  loadRegistry,
  parseAttrs,

  resolveSchema,
  SecretsmithError,
} from "../secretsmith.ts";

const pad16 = (pt: Buffer) =>
  Buffer.concat([
    pt,
    Buffer.alloc(16 - (pt.length % 16), 16 - (pt.length % 16)),
  ]);

function makeV10Blob(key: Buffer, plaintext: Buffer): Buffer {
  const iv = Buffer.alloc(16, 0x20);
  const c = createCipheriv("aes-128-cbc", key, iv);
  return Buffer.concat([
    Buffer.from("v10"),
    c.update(pad16(plaintext)),
    c.final(),
  ]);
}

describe("Secretsmith CLI & Integrations", () => {
  test("secretsmith collections lists available collections", () => {
    const out = execSync("secretsmith collections", { encoding: "utf8" });
    expect(out).toContain("/org/freedesktop/secrets/collection");
  });

  test("secretsmith bw-status reports bitwarden status", () => {
    const out = execSync("secretsmith --json bw-status", { encoding: "utf8" });
    const data = JSON.parse(out);
    expect(data).toHaveProperty("status");
    expect(typeof data.status).toBe("string");
  });

  test("secretsmith cookie-vault sync executes and reports stored cookies", () => {
    const out = execSync("secretsmith cookie-vault status", {
      encoding: "utf8",
    });
    expect(out).toContain("cookies");
  });

  test("tau-auth-sync is wired into the CLI", () => {
    let exit = 0;
    let stderr = "";
    try {
      execSync("secretsmith tau-auth-sync --db-path /nonexistent/agent.db", {
        encoding: "utf8",
        stdio: ["ignore", "ignore", "pipe"],
      });
    } catch (e: any) {
      exit = e.status ?? -1;
      stderr = String(e.stderr ?? "");
    }
    expect(exit).toBe(1);
    expect(stderr).toContain("agent.db not found");
    expect(stderr).not.toContain("Traceback");
  });

  test("registry resolves chromium schema and chrome alias", () => {
    const reg = loadRegistry();
    expect("chromium" in reg.schemas).toBe(true);
    expect(resolveSchema("chromium", reg)[0]).toBe(
      "chrome_libsecret_os_crypt_password_v2",
    );
    expect(resolveSchema("chrome", reg)[0]).toBe(
      "chrome_libsecret_os_crypt_password_v2",
    );
    expect(resolveSchema("generic", reg)[0]).toBe(
      "org.freedesktop.Secret.Generic",
    );
    const [name, entry] = resolveSchema("com.example.Custom", reg);
    expect(name).toBe("com.example.Custom");
    expect(entry.description).toContain("unregistered");
  });

  test("chromium crypto round-trips raw and base64 keys", () => {
    const key = Buffer.from(crypto.getRandomValues(new Uint8Array(16)));
    const blob = makeV10Blob(key, Buffer.from("correct horse"));
    expect(decryptChromiumBlob(blob, [key]).toString()).toBe("correct horse");
    // base64-encoded key candidate path
    const b64Key = Buffer.from(key.toString("base64"));
    const cands = keyCandidates(b64Key);
    expect(cands.length).toBeGreaterThan(0);
    expect(decryptChromiumBlob(blob, cands).toString()).toBe("correct horse");
  });

  test("chromium crypto rejects wrong key and bad prefix", () => {
    const key = Buffer.from(crypto.getRandomValues(new Uint8Array(16)));
    const blob = makeV10Blob(key, Buffer.from("nope"));
    const wrongKey = Buffer.from(crypto.getRandomValues(new Uint8Array(16)));
    expect(() => decryptChromiumBlob(blob, [wrongKey])).toThrow(
      SecretsmithError,
    );
    expect(() =>
      decryptChromiumBlob(
        Buffer.concat([Buffer.from("v99"), Buffer.alloc(32)]),
        [wrongKey],
      ),
    ).toThrow(SecretsmithError);
  });

  test("parse attrs", () => {
    expect(parseAttrs(["a=1", "b=x=y"])).toEqual({ a: "1", b: "x=y" });
    expect(() => parseAttrs(["bare"])).toThrow(SecretsmithError);
  });

  test("redact is removed: --redact fails loudly", () => {
    const res = Bun.spawnSync({
      cmd: ["bun", "secretsmith.ts", "--redact", "get", "--label", "nonexistent-xyz"],
      cwd: import.meta.dir + "/..",
    });
    expect(res.exitCode).not.toBe(0);
    const err = res.stderr.toString();
    expect(err).toContain("--redact was removed");
  });
});

